// Sprites para los héroes (cargados automáticamente o embebidos para compatibilidad local con file://).
const HERO_SPRITE_DATA = {
  aracnido: {
    'cabeza': 'data:image/png;base64,',
    'torso': 'data:image/png;base64,',
    'brazo': 'data:image/png;base64,',
    'antebrazo': 'data:image/png;base64,',
    'mano': 'data:image/png;base64,',
    'muslo': 'data:image/png;base64,',
    'pierna': 'data:image/png;base64,',
    'pie': 'data:image/png;base64,',
    'red': 'data:image/png;base64,',
    'red_gigante': 'data:image/png;base64,',
    'red_atrapado': 'data:image/png;base64,',
  }
};

// Registra las texturas en Phaser
function initHeroTextures(scene) {
  const textures = scene.textures;
  for (const [heroId, parts] of Object.entries(HERO_SPRITE_DATA)) {
    for (const [partName, dataUri] of Object.entries(parts)) {
      const texKey = `${heroId}_${partName}`;
      if (!textures.exists(texKey)) {
        textures.addBase64(texKey, dataUri);
      }
    }
  }
}
